// Verify IQ2_XXS quantization matches llama.cpp using real quantized test data
// The test data was generated by tools/iq_quantizer

use half::f16;
use infer_train::quant::types::*;
use infer_train::quant::weights::iq::*;
use infer_train::quant::weights::iq_grid::{
    IQ2GridData, IQ2XXS_GRID, KGRID_2BIT_256,
};

fn quantize_iq2_xxs_debug(
    x: &[f32],
    quant_weights: Option<&[f32]>,
) -> Vec<BlockIQ2XXS> {
    const QK_K: usize = 256;
    const KMAX_Q: i32 = 3;
    const GROUP_MAX_EPS: f32 = 1e-8;

    assert!(x.len() % QK_K == 0);
    let nb = x.len() / QK_K;
    let mut blocks = Vec::with_capacity(nb);

    // Initialize grid data
    let grid_data = IQ2GridData::new(256, &KGRID_2BIT_256, 2);

    for ibl in 0..nb {
        let xbl = &x[ibl * QK_K..(ibl + 1) * QK_K];

        // Use provided weights or uniform weights
        let quant_weights_slice: Vec<f32> = if let Some(qw) = quant_weights {
            qw[ibl * QK_K..(ibl + 1) * QK_K].to_vec()
        } else {
            vec![1.0; QK_K]
        };

        let mut scales = [0.0f32; QK_K / 32];
        let mut q2 = [0u32; 2 * (QK_K / 32)];
        let mut max_scale = 0.0f32;

        // Compute sigma2 for the block
        let sumx2: f32 = xbl.iter().map(|v| v * v).sum();
        let sigma2 = sumx2 / QK_K as f32;

        if ibl == 0 {
            println!("Block 0: sigma2 = {:.6}", sigma2);
        }

        // Process each sub-block of 32 values
        for ib in 0..QK_K / 32 {
            let xb = &xbl[ib * 32..(ib + 1) * 32];
            let qw = &quant_weights_slice[ib * 32..(ib + 1) * 32];

            // Compute quantization weights
            let mut weight = [0.0f32; 32];
            let mut waux = [0.0f32; 32];
            for i in 0..32 {
                weight[i] = qw[i] * (sigma2 + xb[i] * xb[i]).sqrt();
                waux[i] = weight[i].sqrt();
            }

            // Extract signs and absolute values
            let mut xval = [0.0f32; 32];
            let mut block_signs = [0u8; 4];

            for k in 0..4 {
                let mut nflip = 0;
                let mut s = 0u8;
                for i in 0..8 {
                    if xb[8 * k + i] >= 0.0 {
                        xval[8 * k + i] = xb[8 * k + i];
                    } else {
                        xval[8 * k + i] = -xb[8 * k + i];
                        nflip += 1;
                        s |= 1 << i;
                    }
                }
                // Parity constraint
                if nflip % 2 != 0 {
                    let mut min_idx = 0;
                    let mut min_val = weight[8 * k] * xb[8 * k] * xb[8 * k];
                    for i in 1..8 {
                        let ax =
                            weight[8 * k + i] * xb[8 * k + i] * xb[8 * k + i];
                        if ax < min_val {
                            min_val = ax;
                            min_idx = i;
                        }
                    }
                    xval[8 * k + min_idx] = -xval[8 * k + min_idx];
                    s ^= 1 << min_idx;
                }
                block_signs[k] = s & 127;

                if ibl == 0 && ib == 0 {
                    println!(
                        "  Group {}: nflip={}, s before mask={}, s after &127={}",
                        k, nflip, s, block_signs[k]
                    );
                }
            }

            // Find max
            let max = xval.iter().cloned().fold(0.0f32, f32::max);

            if ibl == 0 && ib == 0 {
                println!(
                    "  Sub-block 0: max = {:.6}, max_abs = {:.6}",
                    max,
                    xb.iter().map(|v| v.abs()).fold(0.0f32, f32::max)
                );
                println!("  xval = {:?}", &xval[0..8]);
            }

            if max < GROUP_MAX_EPS {
                println!("  Sub-block {}: max {:.6} < EPS, skipping", ib, max);
                scales[ib] = 0.0;
                continue;
            }

            // Initial scale using make_qp_quants
            let mut l = [0u8; 32];
            let scale =
                make_qp_quants_debug(32, KMAX_Q + 1, &xval, &mut l, &weight);
            let eff_max = scale * KMAX_Q as f32;

            if ibl == 0 && ib == 0 {
                println!(
                    "  Initial scale = {:.6}, eff_max = {:.6}",
                    scale, eff_max
                );
                println!("  l values = {:?}", &l[0..8]);
            }

            if eff_max <= 0.0 {
                println!(
                    "  Sub-block {}: eff_max {:.6} <= 0, skipping",
                    ib, eff_max
                );
                scales[ib] = 0.0;
                continue;
            }

            // Main scale optimization loop
            let mut best = 0.0f32;
            let mut l_final = [0i8; 32];

            for is in -6..=6 {
                let id = ((2 * KMAX_Q - 1) as f32 + is as f32 * 0.1) / eff_max;
                let this_scale = 1.0 / id;
                let mut laux = [0i8; 32];

                for k in 0..4 {
                    for i in 0..8 {
                        let lval = nearest_int_debug(
                            0.5 * (id * xval[8 * k + i] - 1.0),
                        );
                        laux[8 * k + i] = lval.clamp(0, KMAX_Q - 1) as i8;
                    }
                    let mut u: u16 = 0;
                    for i in 0..8 {
                        u |= (laux[8 * k + i] as u16) << (2 * i);
                    }
                    let grid_index = grid_data.map[u as usize];
                    if grid_index < 0 {
                        // Neighbor handling - simplified for debug
                        let neighbors_idx =
                            (-grid_data.map[u as usize] - 1) as usize;
                        let num_neighbors =
                            grid_data.neighbors[neighbors_idx] as usize;
                        let neighbors = &grid_data.neighbors[neighbors_idx..];
                        find_best_neighbor_iq2_debug(
                            neighbors,
                            &grid_data.grid,
                            &xval[8 * k..8 * (k + 1)],
                            &waux[8 * k..8 * (k + 1)],
                            this_scale,
                            &mut laux[8 * k..8 * (k + 1)],
                        );
                    }
                }

                let sumqx: f32 = (0..32)
                    .map(|i| weight[i] * xval[i] * (2.0 * laux[i] as f32 + 1.0))
                    .sum();
                let sumq2: f32 = (0..32)
                    .map(|i| weight[i] * (2.0 * laux[i] as f32 + 1.0).powi(2))
                    .sum();

                if sumq2 > 0.0 && sumqx * sumqx > best * sumq2 {
                    let new_scale = sumqx / sumq2;
                    best = new_scale * sumqx;
                    l_final.copy_from_slice(&laux);
                }
            }

            if ibl == 0 && ib == 0 {
                println!("  After optimization: best = {:.6}", best);
                println!("  l_final = {:?}", &l_final[0..8]);
            }

            // Handle scale computation
            let mut scale = 0.0f32;
            if best > 0.0 {
                let sumqx: f32 = (0..32)
                    .map(|i| {
                        weight[i] * xval[i] * (2.0 * l_final[i] as f32 + 1.0)
                    })
                    .sum();
                let sumq2: f32 = (0..32)
                    .map(|i| {
                        weight[i] * (2.0 * l_final[i] as f32 + 1.0).powi(2)
                    })
                    .sum();
                if sumq2 > 0.0 {
                    scale = sumqx / sumq2;
                }

                if scale > 0.0 {
                    let id = 1.0 / scale;
                    for k in 0..4 {
                        let mut u: u16 = 0;
                        for i in 0..8 {
                            let l = nearest_int_debug(
                                0.5 * (id * xval[8 * k + i] - 1.0),
                            )
                            .clamp(0, KMAX_Q - 1)
                                as i8;
                            l_final[8 * k + i] = l as i8;
                            u |= (l as u16) << (2 * i);
                        }
                        let grid_index = grid_data.map[u as usize];
                        if grid_index < 0 {
                            let neighbors_idx =
                                (-grid_data.map[u as usize] - 1) as usize;
                            let neighbors =
                                &grid_data.neighbors[neighbors_idx..];
                            find_best_neighbor_iq2_debug(
                                neighbors,
                                &grid_data.grid,
                                &xval[8 * k..8 * (k + 1)],
                                &waux[8 * k..8 * (k + 1)],
                                scale,
                                &mut l_final[8 * k..8 * (k + 1)],
                            );
                        }
                    }

                    let sumqx: f32 = (0..32)
                        .map(|i| {
                            weight[i]
                                * xval[i]
                                * (2.0 * l_final[i] as f32 + 1.0)
                        })
                        .sum();
                    let sumq2: f32 = (0..32)
                        .map(|i| {
                            weight[i] * (2.0 * l_final[i] as f32 + 1.0).powi(2)
                        })
                        .sum();
                    if sumq2 > 0.0 {
                        scale = sumqx / sumq2;
                    }
                }
            }

            if ibl == 0 && ib == 0 {
                println!("  Final scale = {:.6}", scale);
            }

            if scale < 0.0 {
                scale = -scale;
                for k in 0..4 {
                    block_signs[k] = (!block_signs[k]) & 127;
                }
            }

            // Pack grid indices and signs
            for k in 0..4 {
                let mut u: u16 = 0;
                for i in 0..8 {
                    u |= (l_final[8 * k + i] as u16) << (2 * i);
                }
                let grid_index = grid_data.map[u as usize];
                if grid_index < 0 {
                    panic!("Oops: found point {} not on grid", u);
                }
                q2[2 * ib] |= (grid_index as u32) << (8 * k);
                q2[2 * ib + 1] |= (block_signs[k] as u32) << (7 * k);

                if ibl == 0 && ib == 0 {
                    println!(
                        "  Packing group {}: grid_index={}, block_signs={}",
                        k, grid_index, block_signs[k]
                    );
                    println!(
                        "    q2[{}] = {} ({:032b})",
                        2 * ib,
                        q2[2 * ib],
                        q2[2 * ib]
                    );
                    println!(
                        "    q2[{}] = {} ({:032b})",
                        2 * ib + 1,
                        q2[2 * ib + 1],
                        q2[2 * ib + 1]
                    );
                }
            }

            scales[ib] = scale;
            max_scale = max_scale.max(scale);
        }

        if ibl == 0 {
            println!("  max_scale = {:.6}", max_scale);
        }

        if max_scale == 0.0 {
            let mut qs = [0u16; 32];
            blocks.push(BlockIQ2XXS { d: f16::from_f32(0.0).to_bits(), qs });
            continue;
        }

        let d = max_scale / 31.0;
        let id = 1.0 / d;
        for ib in 0..QK_K / 32 {
            let lval = nearest_int_debug(0.5 * (id * scales[ib] - 1.0))
                .clamp(0, 15) as u32;
            q2[2 * ib + 1] |= lval << 28;
        }

        let mut qs = [0u16; 32];
        for i in 0..16 {
            qs[2 * i] = (q2[i] & 0xFFFF) as u16;
            qs[2 * i + 1] = ((q2[i] >> 16) & 0xFFFF) as u16;
        }

        blocks.push(BlockIQ2XXS { d: f16::from_f32(d).to_bits(), qs });
    }
    blocks
}

fn make_qp_quants_debug(
    n: usize,
    nmax: i32,
    x: &[f32],
    l: &mut [u8],
    quant_weights: &[f32],
) -> f32 {
    let max = x.iter().cloned().fold(0.0f32, f32::max);
    if max == 0.0 {
        return 0.0;
    }

    let mut iscale = nmax as f32 / max;
    let mut scale = 1.0 / iscale;

    // Simple initial L values
    for i in 0..n {
        l[i] = nearest_int_debug(iscale * x[i]).min(nmax) as u8;
    }

    scale
}

fn nearest_int(x: f32) -> i32 {
    (x + 0.5).floor() as i32
}

fn nearest_int_debug(x: f32) -> i32 {
    (x + 0.5).floor() as i32
}

fn find_best_neighbor_iq2_debug(
    neighbors: &[u16],
    grid: &[u64],
    xval: &[f32],
    weight: &[f32],
    scale: f32,
    l: &mut [i8],
) {
    let num_neighbors = neighbors[0] as usize;
    let mut best_d2 = f32::MAX;
    let mut best_idx = 0usize;

    for &nj in &neighbors[1..=num_neighbors] {
        let pg = grid[nj as usize].to_le_bytes();
        let mut d2 = 0.0f32;
        for i in 0..8 {
            let q = pg[i] as f32;
            let diff = scale * q - xval[i];
            d2 += weight[i] * diff * diff;
        }
        if d2 < best_d2 {
            best_d2 = d2;
            best_idx = nj as usize;
        }
    }

    let pg = grid[best_idx].to_le_bytes();
    for i in 0..8 {
        l[i] = ((pg[i] as i16 - 1) / 2) as i8;
    }
}

fn main() {
    println!("=== IQ2_XXS Quantization Verification ===\n");

    // Use simple test data that I can verify manually
    // Create a block of 256 floats
    let test_data: Vec<f32> = (0..256)
        .map(|i| {
            // Mix of positive and negative values
            if i % 7 == 0 { -1.0 } else { (i as f32) / 100.0 }
        })
        .collect();

    println!("Input data (first 32): {:?}", &test_data[0..32]);

    // Check data distribution
    let max_val = test_data.iter().cloned().fold(0.0f32, f32::max);
    let min_val = test_data.iter().cloned().fold(0.0f32, f32::min);
    println!("Data range: [{:.3}, {:.3}]", min_val, max_val);

    // Default quantization weights
    let quant_weights: Vec<f32> = vec![1.0; 256];

    // Quantize with debug
    let blocks = quantize_iq2_xxs_debug(&test_data, Some(&quant_weights));

    println!("\nQuantized block 0:");
    println!(
        "  d = {:.6} (FP16 bits: 0x{:04X})",
        f16::from_bits(blocks[0].d).to_f32(),
        blocks[0].d
    );
    println!("  qs[0..4] = {:?}", &blocks[0].qs[0..4]);

    // Dequantize and check
    println!("\nDequantized values:");
    let d = f16::from_bits(blocks[0].d).to_f32();

    // Get first 32-element sub-block (ib=0)
    let q2_0 = (blocks[0].qs[0] as u32) | ((blocks[0].qs[1] as u32) << 16);
    let q2_1 = (blocks[0].qs[2] as u32) | ((blocks[0].qs[3] as u32) << 16);

    let aux8: [u8; 4] = [
        (q2_0 & 0xFF) as u8,
        ((q2_0 >> 8) & 0xFF) as u8,
        ((q2_0 >> 16) & 0xFF) as u8,
        ((q2_0 >> 24) & 0xFF) as u8,
    ];

    let scale_bits = q2_1 >> 28;
    let db = d * (0.5 + scale_bits as f32) * 0.25;

    println!("  Grid indices: {:?}", aux8);
    println!("  Scale bits: {} (db = {:.6})", scale_bits, db);

    // ksigns and kmask tables
    let ksigns_iq2xs: [u8; 128] = [
        0, 129, 130, 3, 132, 5, 6, 135, 136, 9, 10, 139, 12, 141, 142, 15, 144,
        17, 18, 147, 20, 149, 150, 23, 24, 153, 154, 27, 156, 29, 30, 159, 160,
        33, 34, 163, 36, 165, 166, 39, 40, 169, 170, 43, 172, 45, 46, 175, 48,
        177, 178, 51, 180, 53, 54, 183, 184, 57, 58, 187, 60, 189, 190, 63,
        192, 65, 66, 195, 68, 197, 198, 71, 72, 201, 202, 75, 204, 77, 78, 207,
        80, 209, 210, 83, 212, 85, 86, 215, 216, 89, 90, 219, 92, 221, 222, 95,
        96, 225, 226, 99, 228, 101, 102, 231, 232, 105, 106, 235, 108, 237,
        238, 111, 240, 113, 114, 243, 116, 245, 246, 119, 120, 249, 250, 123,
        252, 125, 126, 255,
    ];
    let kmask_iq2xs: [u8; 8] = [1, 2, 4, 8, 16, 32, 64, 128];

    for l in 0..4 {
        let grid_idx = aux8[l] as usize;
        let grid = IQ2XXS_GRID[grid_idx].to_le_bytes();
        let signs_7bit = (q2_1 >> (7 * l)) & 0x7F;
        let signs = ksigns_iq2xs[signs_7bit as usize];

        print!("  Group {}: ", l);
        for j in 0..8 {
            let q = grid[j] as f32;
            let sign =
                if signs & kmask_iq2xs[j] != 0 { -1.0f32 } else { 1.0f32 };
            let val = db * q * sign;
            print!("{:.3} ", val);
        }
        println!();
    }

    // Compare with original
    println!("\nOriginal first 32 values:");
    for i in 0..4 {
        print!("  Group {}: ", i);
        for j in 0..8 {
            print!("{:.3} ", test_data[i * 8 + j]);
        }
        println!();
    }

    // Compute error
    let mut total_error = 0.0f32;
    let mut max_error = 0.0f32;
    let mut count = 0;

    // Dequantize all values
    for l in 0..4 {
        let grid_idx = aux8[l] as usize;
        let grid = IQ2XXS_GRID[grid_idx].to_le_bytes();
        let signs_7bit = (q2_1 >> (7 * l)) & 0x7F;
        let signs = ksigns_iq2xs[signs_7bit as usize];

        for j in 0..8 {
            let q = grid[j] as f32;
            let sign =
                if signs & kmask_iq2xs[j] != 0 { -1.0f32 } else { 1.0f32 };
            let deq_val = db * q * sign;
            let orig_val = test_data[l * 8 + j];
            let error = (deq_val - orig_val).abs();
            total_error += error;
            max_error = max_error.max(error);
            count += 1;
        }
    }

    println!("\nError statistics:");
    println!("  Mean error: {:.6}", total_error / count as f32);
    println!("  Max error: {:.6}", max_error);

    // Now test with random data and compare CPU dequant vs quantized output
    use rand::{Rng, SeedableRng, rngs::StdRng};
    let mut rng = StdRng::seed_from_u64(42);
    let random_data: Vec<f32> = (0..256).map(|_| rng.r#gen::<f32>()).collect();

    println!("\n\n=== Random data test ===");
    let random_blocks = quantize_iq2_xxs(&random_data, Some(&quant_weights));

    // CPU dequantize
    let dequant_values = dequantize_iq2_xxs(&random_blocks);

    // Compare
    let mut errors = Vec::new();
    for i in 0..256 {
        let error = (dequant_values[i] - random_data[i]).abs();
        errors.push(error);
    }

    let mean_error: f32 = errors.iter().sum::<f32>() / 256.0;
    let max_error: f32 = errors.iter().cloned().fold(0.0, f32::max);

    println!("Mean error: {:.6}", mean_error);
    println!("Max error: {:.6}", max_error);

    // Relative error
    let mut rel_errors = Vec::new();
    for i in 0..256 {
        if random_data[i].abs() > 0.01 {
            rel_errors.push(errors[i] / random_data[i].abs());
        }
    }
    let mean_rel_error: f32 =
        rel_errors.iter().sum::<f32>() / rel_errors.len() as f32;
    println!("Mean relative error: {:.2}%", mean_rel_error * 100.0);
}

fn dequantize_iq2_xxs(blocks: &[BlockIQ2XXS]) -> Vec<f32> {
    let mut result = Vec::with_capacity(blocks.len() * 256);

    let ksigns_iq2xs: [u8; 128] = [
        0, 129, 130, 3, 132, 5, 6, 135, 136, 9, 10, 139, 12, 141, 142, 15, 144,
        17, 18, 147, 20, 149, 150, 23, 24, 153, 154, 27, 156, 29, 30, 159, 160,
        33, 34, 163, 36, 165, 166, 39, 40, 169, 170, 43, 172, 45, 46, 175, 48,
        177, 178, 51, 180, 53, 54, 183, 184, 57, 58, 187, 60, 189, 190, 63,
        192, 65, 66, 195, 68, 197, 198, 71, 72, 201, 202, 75, 204, 77, 78, 207,
        80, 209, 210, 83, 212, 85, 86, 215, 216, 89, 90, 219, 92, 221, 222, 95,
        96, 225, 226, 99, 228, 101, 102, 231, 232, 105, 106, 235, 108, 237,
        238, 111, 240, 113, 114, 243, 116, 245, 246, 119, 120, 249, 250, 123,
        252, 125, 126, 255,
    ];
    let kmask_iq2xs: [u8; 8] = [1, 2, 4, 8, 16, 32, 64, 128];

    for block in blocks {
        let d = f16::from_bits(block.d).to_f32();

        for ib in 0..8 {
            let q2_0 = (block.qs[4 * ib] as u32)
                | ((block.qs[4 * ib + 1] as u32) << 16);
            let q2_1 = (block.qs[4 * ib + 2] as u32)
                | ((block.qs[4 * ib + 3] as u32) << 16);

            let aux8: [u8; 4] = [
                (q2_0 & 0xFF) as u8,
                ((q2_0 >> 8) & 0xFF) as u8,
                ((q2_0 >> 16) & 0xFF) as u8,
                ((q2_0 >> 24) & 0xFF) as u8,
            ];

            let scale_bits = q2_1 >> 28;
            let db = d * (0.5 + scale_bits as f32) * 0.25;

            for l in 0..4 {
                let grid_idx = aux8[l] as usize;
                let grid = IQ2XXS_GRID[grid_idx].to_le_bytes();
                let signs_7bit = (q2_1 >> (7 * l)) & 0x7F;
                let signs = ksigns_iq2xs[signs_7bit as usize];

                for j in 0..8 {
                    let q = grid[j] as f32;
                    let sign = if signs & kmask_iq2xs[j] != 0 {
                        -1.0f32
                    } else {
                        1.0f32
                    };
                    result.push(db * q * sign);
                }
            }
        }
    }

    result
}
